<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,useId,watch} from 'vue';
import {Button,Card,Badge,EmptyState,SearchField,StatusNotice,useHostContext} from '@openclaw-plugins/control-ui-kit';
import {useManagementRequest} from './management-request';
import {layoutKnowledgeGraph} from './knowledge-graph-layout';
import type {KnowledgeGraph as Graph} from './knowledge-model';
const props=defineProps<{agentId:string;projectId:string}>(),emit=defineEmits<{open:[path:string]}>();
const context=useHostContext(),request=useManagementRequest(context,()=>props.agentId),graph=ref<Graph>(),loading=ref(false),error=ref(''),query=ref(''),selected=ref('');
const canvas=ref<SVGSVGElement>(),canvasWidth=ref(600);let resize:ResizeObserver|undefined;
watch(canvas,element=>{resize?.disconnect();if(!element)return;const measure=()=>{canvasWidth.value=element.getBoundingClientRect().width||600;};measure();resize=new ResizeObserver(measure);resize.observe(element);});onBeforeUnmount(()=>resize?.disconnect());
const view=ref({x:0,y:0,width:1000,height:600}),drag=ref<{x:number;y:number;startX:number;startY:number;unitX:number;unitY:number;moved:boolean}>();let epoch=0,suppressClick=false;
const marker='kb-edge-'+useId().replace(/[^a-z0-9-]/gi,''),safe=(v:unknown)=>context.value.host.redact(String(v??''));
async function load(){const token=++epoch,valid=request.capture();loading.value=true;graph.value=undefined;error.value='';selected.value='';query.value='';reset();try{const result=await request.invoke<Graph>('knowledgeGraph',{projectId:props.projectId,limit:100});if(valid()&&token===epoch)graph.value=result;}catch{if(valid()&&token===epoch)error.value='图谱读取失败，请核对项目与知识库配置后重试。';}finally{if(valid()&&token===epoch)loading.value=false;}}
const labelLimit=computed(()=>Math.max(8,Math.min(18,Math.floor(canvasWidth.value/55))));
const nodes=computed(()=>graph.value?.nodes??[]),edges=computed(()=>graph.value?.edges??[]),points=computed(()=>layoutKnowledgeGraph(nodes.value,edges.value)),pointMap=computed(()=>new Map(points.value.map(p=>[p.path,p])));
const matches=computed(()=>new Set(nodes.value.filter(n=>[n.title,n.path,n.uid].some(v=>String(v??'').toLowerCase().includes(query.value.trim().toLowerCase()))).map(n=>n.path)));
const current=computed(()=>nodes.value.find(n=>n.path===selected.value)),related=computed(()=>edges.value.filter(e=>e.source===selected.value||e.target===selected.value));
const neighbors=computed(()=>new Set([selected.value,...related.value.flatMap(e=>[e.source,e.target])]));
const relationLabel=(value?:string)=>(({references:'引用',part_of:'属于',depends_on:'依赖',constrained_by:'受约束于',implements:'实现',supersedes:'替代'} as Record<string,string>)[value??'']??'关联');
function choose(path:string,center=false){if(suppressClick)return;selected.value=path;if(center){const point=pointMap.value.get(path);if(point)view.value={...view.value,x:point.x-view.value.width/2,y:point.y-view.value.height/2};}}
function search(value:string){query.value=value;const first=nodes.value.find(n=>matches.value.has(n.path));if(first)choose(first.path,true);}
function reset(){view.value={x:0,y:0,width:1000,height:600};}
function zoom(factor:number){const old=view.value,width=Math.max(300,Math.min(2500,old.width*factor)),height=width*.6;view.value={x:old.x+(old.width-width)/2,y:old.y+(old.height-height)/2,width,height};}
function pointerDown(event:PointerEvent){if(event.button!==0)return;const svg=event.currentTarget as SVGSVGElement,rect=svg.getBoundingClientRect();if(!rect.width||!rect.height)return;drag.value={x:event.clientX,y:event.clientY,startX:view.value.x,startY:view.value.y,unitX:Math.max(view.value.width/rect.width,view.value.height/rect.height),unitY:Math.max(view.value.width/rect.width,view.value.height/rect.height),moved:false};suppressClick=false;}
function pointerMove(event:PointerEvent){const d=drag.value;if(!d)return;const dx=event.clientX-d.x,dy=event.clientY-d.y;if(Math.hypot(dx,dy)>4)d.moved=true;if(d.moved)(event.currentTarget as SVGSVGElement).setPointerCapture?.(event.pointerId);if(d.moved)view.value={...view.value,x:d.startX-dx*d.unitX,y:d.startY-dy*d.unitY};}
function pointerUp(){suppressClick=drag.value?.moved??false;drag.value=undefined;}
function svgKey(event:KeyboardEvent){if(event.target!==event.currentTarget)return;const direction:Record<string,[number,number]>={ArrowLeft:[-.1,0],ArrowRight:[.1,0],ArrowUp:[0,-.1],ArrowDown:[0,.1]};const move=direction[event.key];if(move){event.preventDefault();view.value={...view.value,x:view.value.x+move[0]*view.value.width,y:view.value.y+move[1]*view.value.height};}}
watch(()=>props.projectId,load,{flush:'sync'});onMounted(load);
</script>
<template>
 <section class="kb-graph" aria-label="知识库图谱" :aria-busy="loading">
  <div class="kb-graph-toolbar"><SearchField v-model="query" aria-label="查找图谱文档" placeholder="查找标题、路径或 UID" :disabled="!nodes.length" @search="search"/><div class="kb-graph-actions"><Button variant="outline" size="sm" :disabled="!nodes.length" aria-label="放大图谱" @click="zoom(.8)">放大</Button><Button variant="outline" size="sm" :disabled="!nodes.length" aria-label="缩小图谱" @click="zoom(1.25)">缩小</Button><Button variant="outline" size="sm" :disabled="!nodes.length" @click="reset">适应画布</Button><Button variant="outline" size="sm" :disabled="loading" @click="load">刷新图谱</Button></div></div>
  <p v-if="loading" role="status">正在构建文档引用图谱…</p>
  <StatusNotice v-if="error" tone="error">{{error}}<template #actions><Button variant="outline" @click="load">重试图谱</Button></template></StatusNotice>
  <template v-if="graph">
   <div class="kb-graph-scope"><span>{{safe(graph.knowledgePath)}}</span><Badge variant="outline">{{safe(graph.metadataNamespace)}}</Badge><Badge variant="secondary">{{graph.normalized?'规范化知识库':'普通 wiki'}}</Badge></div>
   <EmptyState v-if="!graph.available" title="项目尚无知识库目录" description="请添加 wiki 目录或配置知识库路径。"/>
   <EmptyState v-else-if="!nodes.length" title="知识库暂无 Markdown 条目。" description="添加文档与引用关系后，可在此查看图谱。"/>
   <template v-else>
    <StatusNotice v-if="!graph.complete||graph.truncated" tone="warning">图谱仅展示本次可读取的部分内容（最多 {{graph.nodeLimit}} 篇、{{graph.edgeLimit}} 条关系）。请结合文档列表和结构校验核对。</StatusNotice>
    <div class="kb-graph-summary" role="status"><span>{{nodes.length}} / {{graph.totalNodes}} 篇文档 · {{edges.length}} 条关系</span><span v-if="query.trim()">{{matches.size}} 项匹配</span><span v-if="graph.unresolvedReferences">{{graph.unresolvedReferences}} 项引用未解析</span><span v-if="graph.invalidDocuments">{{graph.invalidDocuments}} 篇元数据无效</span></div>
    <div class="kb-graph-workspace">
     <Card class="kb-graph-canvas"><svg ref="canvas" class="kb-network" :viewBox="`${view.x} ${view.y} ${view.width} ${view.height}`" role="group" aria-label="文档引用关系画布" tabindex="0" @keydown="svgKey" @pointerdown="pointerDown" @pointermove="pointerMove" @pointerup="pointerUp" @pointercancel="pointerUp">
      <title>知识库文档与引用关系</title><defs><marker :id="marker" viewBox="0 0 10 10" refX="25" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>
      <g class="kb-graph-edges"><line v-for="(edge,i) in edges" :key="i" :x1="pointMap.get(edge.source)?.x" :y1="pointMap.get(edge.source)?.y" :x2="pointMap.get(edge.target)?.x" :y2="pointMap.get(edge.target)?.y" :class="{metadata:edge.kind==='relation',active:selected&&(edge.source===selected||edge.target===selected),dim:selected&&edge.source!==selected&&edge.target!==selected}" :marker-end="`url(#${marker})`"><title>{{edge.kind==='link'?'文档链接':relationLabel(edge.relation)}}</title></line></g>
      <g v-for="node in nodes" :key="node.path" role="button" tabindex="0" :aria-label="'选择文档 '+safe(node.title)+' · '+safe(node.path)" :aria-pressed="selected===node.path" :transform="`translate(${pointMap.get(node.path)?.x??0},${pointMap.get(node.path)?.y??0})`" class="kb-graph-node" :class="{selected:selected===node.path,dim:(query.trim()&&!matches.has(node.path))||(selected&&!neighbors.has(node.path))}" @click="choose(node.path)" @keydown.enter.prevent="suppressClick=false;choose(node.path)" @keydown.space.prevent="suppressClick=false;choose(node.path)"><title>{{safe(node.title)}} · {{safe(node.path)}}</title><circle :r="Math.min(17,9+(pointMap.get(node.path)?.degree??0)*1.2)"/><text v-if="nodes.length<=24||selected===node.path||query.trim()&&matches.has(node.path)" :y="Math.min(17,9+(pointMap.get(node.path)?.degree??0)*1.2)+18*view.width/canvasWidth" :style="{fontSize:(13*view.width/canvasWidth)+'px'}" text-anchor="middle">{{safe(node.title).slice(0,labelLimit)}}{{safe(node.title).length>labelLimit?'…':''}}</text></g>
     </svg><div class="kb-graph-legend"><span><i/>文档链接</span><span><i class="metadata"/>元数据关系</span><small>箭头由来源指向目标；拖动画布或使用方向键平移。</small></div></Card>
     <Card class="kb-graph-detail"><template v-if="current"><h3>{{safe(current.title)}}</h3><p>{{safe(current.path)}}</p><p v-if="current.uid">UID：{{safe(current.uid)}}</p><Button @click="emit('open',current.path)">打开文档</Button><h4>相关关系 · {{related.length}}</h4><p v-if="!related.length">此文档暂无已解析的关联。</p><ul><li v-for="(edge,i) in related" :key="i"><span>{{edge.source===selected?'指向':'来自'}} · {{edge.kind==='link'?'文档链接':relationLabel(edge.relation)}}</span><Button variant="link" @click="suppressClick=false;choose(edge.source===selected?edge.target:edge.source,true)">{{safe(nodes.find(n=>n.path===(edge.source===selected?edge.target:edge.source))?.title)}}</Button></li></ul></template><EmptyState v-else compact title="选择节点查看关联" description="选中文档后可打开正文，或沿引用关系继续查看。"/></Card>
    </div>
    <details class="kb-graph-directory"><summary>文档索引（{{nodes.length}}）</summary><div><Button v-for="node in nodes.filter(n=>matches.has(n.path))" :key="node.path" variant="ghost" @click="suppressClick=false;choose(node.path,true)">{{safe(node.title)}} · {{safe(node.path)}}</Button></div></details>
    <p class="kb-graph-note">仅展示当前知识库内的 Markdown 链接和已解析的 UID 关系。外部链接、图片、代码示例和跨库目标不构成连线；图谱不代表内容已核验。</p>
   </template>
  </template>
 </section>
</template>
<style scoped>
.kb-graph{min-width:0}.kb-graph-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:4px 0 16px}.kb-graph-toolbar>form{flex:1;min-width:200px}.kb-graph-actions{display:flex;gap:6px;flex-wrap:wrap}.kb-graph-scope,.kb-graph-summary{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:12px;color:var(--ocp-muted);margin:12px 0}.kb-graph-scope>span{overflow-wrap:anywhere}.kb-graph-summary{justify-content:space-between}.kb-graph-workspace{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:16px}.kb-graph-canvas{min-width:0;overflow:hidden;padding:0;gap:0;background:var(--ocp-muted-background)}.kb-network{display:block;width:100%;height:460px;touch-action:none;cursor:grab;user-select:none}.kb-network:active{cursor:grabbing}.kb-graph-edges line{stroke:var(--ocp-muted);stroke-width:1.2;opacity:.5}.kb-graph-edges line.metadata{stroke-dasharray:6 4}.kb-graph-edges line.active{stroke:var(--ocp-primary);stroke-width:2;opacity:1}.kb-graph-edges line.dim{opacity:.12}.kb-network marker path{fill:var(--ocp-muted)}.kb-graph-node{cursor:pointer;outline:none}.kb-graph-node circle{fill:var(--ocp-primary);stroke:var(--ocp-background);stroke-width:3}.kb-graph-node.selected circle,.kb-graph-node:focus-visible circle{stroke:var(--ocp-ring);stroke-width:5}.kb-graph-node text{fill:var(--ocp-foreground);font-size:13px;paint-order:stroke;stroke:var(--ocp-muted-background);stroke-width:4px;stroke-linejoin:round}.kb-graph-node.dim{opacity:.2}.kb-graph-legend{padding:12px 16px;display:flex;gap:12px;flex-wrap:wrap;border-top:1px solid var(--ocp-border);font-size:12px;color:var(--ocp-muted)}.kb-graph-legend span{display:flex;align-items:center;gap:6px}.kb-graph-legend i{width:18px;border-top:1px solid var(--ocp-muted)}.kb-graph-legend i.metadata{border-top-style:dashed}.kb-graph-legend small{flex-basis:100%}.kb-graph-detail{padding:18px;gap:12px;min-width:0;align-self:start}.kb-graph-detail h3,.kb-graph-detail h4{margin:0;font-size:14px;font-weight:600}.kb-graph-detail h4{font-size:12px}.kb-graph-detail p{margin:0;font-size:12px;overflow-wrap:anywhere;color:var(--ocp-muted)}.kb-graph-detail ul{list-style:none;padding:0;margin:0;max-height:260px;overflow:auto}.kb-graph-detail li{display:flex;align-items:flex-start;flex-direction:column;font-size:12px;margin:8px 0}.kb-graph-detail li>span{color:var(--ocp-muted)}.kb-graph-detail li button{padding:0;white-space:normal;height:auto;text-align:start;overflow-wrap:anywhere}.kb-graph-directory{margin:16px 0;font-size:12px}.kb-graph-directory summary{cursor:pointer}.kb-graph-directory>div{display:flex;flex-direction:column;max-height:240px;overflow:auto;margin-top:8px}.kb-graph-directory button{justify-content:flex-start;white-space:normal;height:auto;text-align:start;overflow-wrap:anywhere}.kb-graph-note{font-size:12px;color:var(--ocp-muted);line-height:1.7}.kb-network:focus-visible{outline:2px solid var(--ocp-ring);outline-offset:-3px}@media(max-width:850px){.kb-graph-workspace{grid-template-columns:1fr}.kb-network{height:360px}.kb-graph-detail{align-self:stretch}.kb-graph-toolbar>form{min-width:0;flex-basis:100%}}
</style>
